// Some portions generated by Co-Pilot
import React from "react";
import { render, screen, fireEvent } from "@testing-library/react";
import { describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import Adopters from "../page";
import adopters from "@/data/adopters.json";

vi.unmock("@/data/adopters.json");

vi.mock("next/navigation", async () => ({
  useSearchParams: () => ({
    get: () => null,
  }),
}));

describe("Adopters page", () => {
  it("renders correctly", () => {
    const { container } = render(<Adopters />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<Adopters />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("preserves every adopter and shows the coloured Microsoft logo on a white card", () => {
    const { container } = render(<Adopters />);
    expect(container.querySelectorAll("#adopters a")).toHaveLength(
      adopters.length,
    );
    for (const adopter of adopters)
      expect(screen.getByRole("link", { name: adopter.name })).toHaveAttribute(
        "href",
        adopter.url,
      );
    expect(screen.getByRole("img", { name: "Microsoft" })).not.toHaveClass(
      "brightness-0",
      "invert",
    );
    expect(screen.getAllByRole("heading", { level: 1 })).toHaveLength(1);
    expect(container.querySelector("a button")).not.toBeInTheDocument();
  });

  it("keeps the header submission action and both contribution routes available", () => {
    render(<Adopters />);
    expect(
      screen.getByRole("link", { name: "How can I get my logo displayed?" }),
    ).toHaveAttribute("href", "/adopters?open=adopter#become-adopter");
    fireEvent.click(
      screen.getByRole("button", { name: "How can I get my logo displayed?" }),
    );
    expect(
      screen.getByRole("link", { name: "Temurin Adopters Form" }),
    ).toHaveAttribute("href", expect.stringContaining("template=adopters.yml"));
    expect(screen.getByRole("link", { name: "codebase" })).toHaveAttribute(
      "href",
      "https://gitlab.eclipse.org/eclipsefdn/it/api/eclipsefdn-project-adopters",
    );
  });
});
